B.ahL=new A.q("\u0412\u0435\u0440\u0430","\u041a\u0430\u043a \u0437\u0432\u0443\u0447\u0438\u0442 \u0448\u0430\u0445\u0430\u0434\u0430?","\xab\u0410\u0448\u0445\u0430\u0434\u0443 \u0430\u043b\u044c-\u043b\u044f \u0438\u043b\u044f\u0445\u0430 \u0438\u043b\u043b\u044f\u043b\u043b\u0430\u0445, \u0432\u0430 \u0430\u0448\u0445\u0430\u0434\u0443 \u0430\u043d\u043d\u0430 \u041c\u0443\u0445\u0430\u043c\u043c\u0430\u0434\u0430\u043d \u0440\u0430\u0441\u0443\u043b\u044e\u043b\u043b\u0430\u0445\xbb \u2014 \xab\u0421\u0432\u0438\u0434\u0435\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0443\u044e, \u0447\u0442\u043e \u043d\u0435\u0442 \u0431\u043e\u0436\u0435\u0441\u0442\u0432\u0430, \u043a\u0440\u043e\u043c\u0435 \u0410\u043b\u043b\u0430\u0445\u0430, \u0438 \u0441\u0432\u0438\u0434\u0435\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0443\u044e, \u0447\u0442\u043e \u041c\u0443\u0445\u0430\u043c\u043c\u0430\u0434 \u2014 \u041f\u043e\u0441\u043b\u0430\u043d\u043d\u0438\u043a \u0410\u043b\u043b\u0430\u0445\u0430\xbb.")
B.aiV=new A.q("\u0412\u0435\u0440\u0430","\u0427\u0442\u043e \u0442\u0430\u043a\u043e\u0435 \u0448\u0438\u0440\u043a?","\u041f\u0440\u0438\u0434\u0430\u0432\u0430\u0442\u044c \u0410\u043b\u043b\u0430\u0445\u0443 \u0441\u043e\u0442\u043e\u0432\u0430\u0440\u0438\u0449\u0435\u0439 \u2014 \u0432 \u0431\u043e\u0436\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0441\u0442\u0438 \u0438\u043b\u0438 \u0432 \u043f\u043e\u043a\u043b\u043e\u043d\u0435\u043d\u0438\u0438. \u042d\u0442\u043e \u0441\u0430\u043c\u044b\u0439 \u0442\u044f\u0436\u0451\u043b\u044b\u0439 \u0433\u0440\u0435\u0445: \u0410\u043b\u043b\u0430\u0445 \u043d\u0435 \u043f\u0440\u043e\u0449\u0430\u0435\u0442 \u0435\u0433\u043e \u0442\u043e\u043c\u0443, \u043a\u0442\u043e \u0443\u043c\u0435\u0440 \u043d\u0430 \u043d\u0451\u043c \u0431\u0435\u0437 \u043f\u043e\u043a\u0430\u044f\u043d\u0438\u044f (\u041a\u043e\u0440\u0430\u043d, 4:48).")
B.akM=new A.q("\u0412\u0435\u0440\u0430","\u041a\u0430\u043a\u043e\u0439 \u0430\u043a\u044b\u0434\u044b \u043f\u0440\u0438\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u044e\u0442\u0441\u044f \u043c\u0443\u0441\u0443\u043b\u044c\u043c\u0430\u043d\u0435 \u041a\u0430\u0437\u0430\u0445\u0441\u0442\u0430\u043d\u0430?","\u0410\u043a\u044b\u0434\u044b \u0430\u0445\u043b\u044e-\u0441\u0443\u043d\u043d\u0430 \u0432\u0430\u043b\u044c-\u0434\u0436\u0430\u043c\u0430\u0430 \u043f\u043e \u0448\u043a\u043e\u043b\u0435 \u0438\u043c\u0430\u043c\u0430 \u0410\u0431\u0443 \u041c\u0430\u043d\u0441\u0443\u0440\u0430 \u0430\u043b\u044c-\u041c\u0430\u0442\u0443\u0440\u0438\u0434\u0438, \u0430 \u0432 \u0444\u0438\u043a\u0445\u0435 \u2014 \u0445\u0430\u043d\u0430\u0444\u0438\u0442\u0441\u043a\u043e\u0433\u043e \u043c\u0430\u0437\u0445\u0430\u0431\u0430.")
B.ahv=new A.q("\u0412\u0435\u0440\u0430","\u041a\u0442\u043e \u0442\u0430\u043a\u043e\u0439 \u0438\u043c\u0430\u043c \u0410\u0431\u0443 \u0425\u0430\u043d\u0438\u0444\u0430?","\u041d\u0443\u043c\u0430\u043d \u0438\u0431\u043d \u0421\u0430\u0431\u0438\u0442 (80\u2013150 \u0433. \u0445.), \u0432\u0435\u043b\u0438\u043a\u0438\u0439 \u0443\u0447\u0451\u043d\u044b\u0439 \u0438\u0437 \u041a\u0443\u0444\u044b, \u043e\u0441\u043d\u043e\u0432\u0430\u0442\u0435\u043b\u044c \u0445\u0430\u043d\u0430\u0444\u0438\u0442\u0441\u043a\u043e\u0433\u043e \u043c\u0430\u0437\u0445\u0430\u0431\u0430. \u0415\u0433\u043e \u0443\u0447\u0435\u043d\u0438\u043a\u0438 \u2014 \u0410\u0431\u0443 \u042e\u0441\u0443\u0444 \u0438 \u041c\u0443\u0445\u0430\u043c\u043c\u0430\u0434 \u0430\u0448-\u0428\u0430\u0439\u0431\u0430\u043d\u0438.")
B.aiv=new A.q("\u0412\u0435\u0440\u0430","\u0427\u0442\u043e \u0442\u0430\u043a\u043e\u0435 \u043c\u0430\u0437\u0445\u0430\u0431 \u0438 \u0437\u0430\u0447\u0435\u043c \u0435\u043c\u0443 \u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u044c?","\u041c\u0430\u0437\u0445\u0430\u0431 \u2014 \u0448\u043a\u043e\u043b\u0430 \u043f\u043e\u043d\u0438\u043c\u0430\u043d\u0438\u044f \u0448\u0430\u0440\u0438\u0430\u0442\u0430, \u0432\u044b\u0432\u0435\u0434\u0435\u043d\u043d\u0430\u044f \u0432\u0435\u043b\u0438\u043a\u0438\u043c\u0438 \u0443\u0447\u0451\u043d\u044b\u043c\u0438 \u0438\u0437 \u041a\u043e\u0440\u0430\u043d\u0430 \u0438 \u0421\u0443\u043d\u043d\u044b. \u0421\u043b\u0435\u0434\u0443\u044f \u043e\u0434\u043d\u043e\u043c\u0443 \u043c\u0430\u0437\u0445\u0430\u0431\u0443, \u0447\u0435\u043b\u043e\u0432\u0435\u043a \u043f\u043e\u043a\u043b\u043e\u043d\u044f\u0435\u0442\u0441\u044f \u043f\u0440\u0430\u0432\u0438\u043b\u044c\u043d\u043e \u0438 \u043d\u0435 \u0432\u044b\u0431\u0438\u0440\u0430\u0435\u0442 \xab\u0443\u0434\u043e\u0431\u043d\u043e\u0435\xbb \u0438\u0437 \u0440\u0430\u0437\u043d\u044b\u0445 \u043c\u043d\u0435\u043d\u0438\u0439.")
B.akw=new A.q("\u0422\u0430\u0445\u0430\u0440\u0430\u0442","\u0427\u0442\u043e \u0442\u0430\u043a\u043e\u0435 \u043d\u0430\u0434\u0436\u0430\u0441 (\u043d\u0435\u0447\u0438\u0441\u0442\u043e\u0442\u0430)?","\u041d\u0430\u043f\u0440\u0438\u043c\u0435\u0440: \u043c\u043e\u0447\u0430, \u043a\u0430\u043b, \u0432\u044b\u0442\u0435\u043a\u0448\u0430\u044f \u043a\u0440\u043e\u0432\u044c, \u0433\u043d\u043e\u0439, \u0440\u0432\u043e\u0442\u0430 \u043f\u043e\u043b\u043d\u044b\u043c \u0440\u0442\u043e\u043c, \u0441\u043f\u0438\u0440\u0442\u043d\u043e\u0435, \u0441\u0432\u0438\u043d\u0438\u043d\u0430, \u043c\u0435\u0440\u0442\u0432\u0435\u0447\u0438\u043d\u0430. \u041d\u0430\u0434\u0436\u0430\u0441 \u043d\u0443\u0436\u043d\u043e \u0441\u043c\u044b\u0442\u044c \u0441 \u0442\u0435\u043b\u0430, \u043e\u0434\u0435\u0436\u0434\u044b \u0438 \u043c\u0435\u0441\u0442\u0430 \u043d\u0430\u043c\u0430\u0437\u0430.")
B.alc=new A.q("\u0422\u0430\u0445\u0430\u0440\u0430\u0442","\u041a\u0430\u043a\u0438\u0435 \u0441\u0443\u043d\u043d\u044b \u0443 \u043e\u043c\u043e\u0432\u0435\u043d\u0438\u044f?","\u041d\u0430\u043c\u0435\u0440\u0435\u043d\u0438\u0435, \xab\u0411\u0438\u0441\u043c\u0438\u043b\u043b\u044f\u0445\xbb, \u043c\u044b\u0442\u044c\u0451 \u043a\u0438\u0441\u0442\u0435\u0439 \u0440\u0443\u043a \u0442\u0440\u0438\u0436\u0434\u044b, \u043c\u0438\u0441\u0432\u0430\u043a, \u043f\u043e\u043b\u043e\u0441\u043a\u0430\u043d\u0438\u0435 \u0440\u0442\u0430 \u0438 \u043d\u043e\u0441\u0430, \u043f\u0440\u043e\u0442\u0438\u0440\u0430\u043d\u0438\u0435 \u0432\u0441\u0435\u0439 \u0433\u043e\u043b\u043e\u0432\u044b \u0438 \u0443\u0448\u0435\u0439, \u0442\u0440\u043e\u0435\u043a\u0440\u0430\u0442\u043d\u043e\u0435 \u043c\u044b\u0442\u044c\u0451 \u043a\u0430\u0436\u0434\u043e\u0439 \u0447\u0430\u0441\u0442\u0438, \u043f\u043e\u0440\u044f\u0434\u043e\u043a \u0438 \u043d\u0435\u043f\u0440\u0435\u0440\u044b\u0432\u043d\u043e\u0441\u0442\u044c, \u043c\u044b\u0442\u044c\u0451 \u043c\u0435\u0436\u0434\u0443 \u043f\u0430\u043b\u044c\u0446\u0430\u043c\u0438.")
B.ajZ=new A.q("\u0422\u0430\u0445\u0430\u0440\u0430\u0442","\u041d\u0430\u0440\u0443\u0448\u0430\u0435\u0442 \u043b\u0438 \u043e\u043c\u043e\u0432\u0435\u043d\u0438\u0435 \u043f\u0440\u0438\u043a\u043e\u0441\u043d\u043e\u0432\u0435\u043d\u0438\u0435 \u043a \u0436\u0435\u043d\u0449\u0438\u043d\u0435?","\u041f\u043e \u0445\u0430\u043d\u0430\u0444\u0438\u0442\u0441\u043a\u043e\u043c\u0443 \u043c\u0430\u0437\u0445\u0430\u0431\u0443 \u2014 \u043d\u0435\u0442, \u043f\u0440\u043e\u0441\u0442\u043e\u0435 \u043f\u0440\u0438\u043a\u043e\u0441\u043d\u043e\u0432\u0435\u043d\u0438\u0435 \u043e\u043c\u043e\u0432\u0435\u043d\u0438\u0435 \u043d\u0435 \u043d\u0430\u0440\u0443\u0448\u0430\u0435\u0442.")
B.alY=new A.q("\u0422\u0430\u0445\u0430\u0440\u0430\u0442","\u041d\u0430\u0440\u0443\u0448\u0430\u0435\u0442 \u043b\u0438 \u043e\u043c\u043e\u0432\u0435\u043d\u0438\u0435 \u0433\u0440\u043e\u043c\u043a\u0438\u0439 \u0441\u043c\u0435\u0445?","\u0413\u0440\u043e\u043c\u043a\u0438\u0439 \u0441\u043c\u0435\u0445 (\u043a\u0430\u0445\u043a\u0430\u0445\u0430) \u0432\u0437\u0440\u043e\u0441\u043b\u043e\u0433\u043e \u0432 \u043d\u0430\u043c\u0430\u0437\u0435 \u0441 \u043f\u043e\u043a\u043b\u043e\u043d\u0430\u043c\u0438 \u043d\u0430\u0440\u0443\u0448\u0430\u0435\u0442 \u0438 \u043d\u0430\u043c\u0430\u0437, \u0438 \u043e\u043c\u043e\u0432\u0435\u043d\u0438\u0435. \u0412\u043d\u0435 \u043d\u0430\u043c\u0430\u0437\u0430 \u043e\u043c\u043e\u0432\u0435\u043d\u0438\u0435 \u043e\u043d \u043d\u0435 \u043d\u0430\u0440\u0443\u0448\u0430\u0435\u0442.")
B.ahX=new A.q("\u0422\u0430\u0445\u0430\u0440\u0430\u0442","\u041d\u0430\u0440\u0443\u0448\u0430\u0435\u0442 \u043b\u0438 \u043e\u043c\u043e\u0432\u0435\u043d\u0438\u0435 \u0441\u043e\u043d?","\u0421\u043e\u043d \u043b\u0451\u0436\u0430, \u043d\u0430 \u0431\u043e\u043a\u0443 \u0438\u043b\u0438 \u043e\u0431\u043b\u043e\u043a\u043e\u0442\u0438\u0432\u0448\u0438\u0441\u044c \u043d\u0430\u0440\u0443\u0448\u0430\u0435\u0442 \u043e\u043c\u043e\u0432\u0435\u043d\u0438\u0435. \u0421\u043e\u043d \u0441\u0438\u0434\u044f \u0443\u0441\u0442\u043e\u0439\u0447\u0438\u0432\u043e, \u043f\u043b\u043e\u0442\u043d\u043e \u043d\u0430 \u043c\u0435\u0441\u0442\u0435 \u2014 \u043d\u0435 \u043d\u0430\u0440\u0443\u0448\u0430\u0435\u0442.")
B.aks=new A.q("\u0422\u0430\u0445\u0430\u0440\u0430\u0442","\u0427\u0442\u043e \u0442\u0430\u043a\u043e\u0435 \u043c\u0430\u0441\u0445 \u043d\u0430 \u0445\u0443\u0444\u044b?","\u041f\u0440\u043e\u0442\u0438\u0440\u0430\u043d\u0438\u0435 \u043a\u043e\u0436\u0430\u043d\u044b\u0445 \u043d\u043e\u0441\u043a\u043e\u0432 (\u0445\u0443\u0444\u043e\u0432), \u043d\u0430\u0434\u0435\u0442\u044b\u0445 \u043f\u043e\u0441\u043b\u0435 \u043f\u043e\u043b\u043d\u043e\u0433\u043e \u043e\u043c\u043e\u0432\u0435\u043d\u0438\u044f. \u0421\u0440\u043e\u043a \u2014 \u0441\u0443\u0442\u043a\u0438 \u0434\u043b\u044f \u043c\u0435\u0441\u0442\u043d\u043e\u0433\u043e \u0438 \u0442\u0440\u043e\u0435 \u0441\u0443\u0442\u043e\u043a \u0434\u043b\u044f \u043f\u0443\u0442\u043d\u0438\u043a\u0430. \u041f\u0440\u043e\u0442\u0438\u0440\u0430\u044e\u0442 \u0432\u0435\u0440\u0445 \u0445\u0443\u0444\u0430 \u0442\u0440\u0435\u043c\u044f \u043f\u0430\u043b\u044c\u0446\u0430\u043c\u0438.")
B.ahK=new A.q("\u0422\u0430\u0445\u0430\u0440\u0430\u0442","\u041a\u043e\u0433\u0434\u0430 \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u0435\u043d \u0433\u0443\u0441\u043b\u044c (\u043f\u043e\u043b\u043d\u043e\u0435 \u043e\u043c\u043e\u0432\u0435\u043d\u0438\u0435)?","\u041f\u043e\u0441\u043b\u0435 \u0431\u043b\u0438\u0437\u043e\u0441\u0442\u0438 \u043c\u0435\u0436\u0434\u0443 \u0441\u0443\u043f\u0440\u0443\u0433\u0430\u043c\u0438, \u043f\u043e\u0441\u043b\u0435 \u0432\u044b\u0434\u0435\u043b\u0435\u043d\u0438\u044f \u0441\u0435\u043c\u0435\u043d\u0438, \u043f\u043e \u043e\u043a\u043e\u043d\u0447\u0430\u043d\u0438\u0438 \u043c\u0435\u0441\u044f\u0447\u043d\u044b\u0445 \u0438 \u043f\u043e\u0441\u043b\u0435\u0440\u043e\u0434\u043e\u0432\u044b\u0445 \u043a\u0440\u043e\u0432\u043e\u0442\u0435\u0447\u0435\u043d\u0438\u0439.")
B.akk=new A.q("\u0422\u0430\u0445\u0430\u0440\u0430\u0442","\u0427\u0442\u043e \u0442\u0430\u043a\u043e\u0435 \u0442\u0430\u044f\u043c\u043c\u0443\u043c \u0438 \u043a\u043e\u0433\u0434\u0430 \u043e\u043d \u0440\u0430\u0437\u0440\u0435\u0448\u0451\u043d?","\u041e\u0447\u0438\u0449\u0435\u043d\u0438\u0435 \u0447\u0438\u0441\u0442\u043e\u0439 \u0437\u0435\u043c\u043b\u0451\u0439, \u0435\u0441\u043b\u0438 \u0432\u043e\u0434\u044b \u043d\u0435\u0442 \u043f\u043e\u0431\u043b\u0438\u0437\u043e\u0441\u0442\u0438 (\u043e\u043a\u043e\u043b\u043e 1,8 \u043a\u043c) \u0438\u043b\u0438 \u0432\u043e\u0434\u0430 \u0432\u0440\u0435\u0434\u043d\u0430 \u0434\u043b\u044f \u0437\u0434\u043e\u0440\u043e\u0432\u044c\u044f. \u0423\u0434\u0430\u0440\u044f\u044e\u0442 \u043b\u0430\u0434\u043e\u043d\u044f\u043c\u0438 \u043e \u0437\u0435\u043c\u043b\u044e \u0438 \u043f\u0440\u043e\u0442\u0438\u0440\u0430\u044e\u0442 \u043b\u0438\u0446\u043e, \u0437\u0430\u0442\u0435\u043c \u0441\u043d\u043e\u0432\u0430 \u2014 \u0440\u0443\u043a\u0438 \u0434\u043e \u043b\u043e\u043a\u0442\u0435\u0439.")
B.ajs=new A.q("\u0422\u0430\u0445\u0430\u0440\u0430\u0442","\u0427\u0442\u043e \u0434\u0435\u043b\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u0441\u043e\u043c\u043d\u0435\u0432\u0430\u0435\u0448\u044c\u0441\u044f, \u0435\u0441\u0442\u044c \u043b\u0438 \u043e\u043c\u043e\u0432\u0435\u043d\u0438\u0435?","\u0415\u0441\u043b\u0438 \u0431\u044b\u043b \u0443\u0432\u0435\u0440\u0435\u043d, \u0447\u0442\u043e \u043e\u043c\u043e\u0432\u0435\u043d\u0438\u0435 \u0435\u0441\u0442\u044c, \u0430 \u043f\u043e\u0442\u043e\u043c \u0437\u0430\u0441\u043e\u043c\u043d\u0435\u0432\u0430\u043b\u0441\u044f, \u043d\u0430\u0440\u0443\u0448\u0438\u043b \u043b\u0438 \u0435\u0433\u043e, \u2014 \u043e\u043c\u043e\u0432\u0435\u043d\u0438\u0435 \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044f \u0441\u043e\u0445\u0440\u0430\u043d\u0451\u043d\u043d\u044b\u043c. \u0423\u0432\u0435\u0440\u0435\u043d\u043d\u043e\u0441\u0442\u044c \u043d\u0435 \u043e\u0442\u043c\u0435\u043d\u044f\u0435\u0442\u0441\u044f \u0441\u043e\u043c\u043d\u0435\u043d\u0438\u0435\u043c.")
B.akA=new A.q("\u041d\u0430\u043c\u0430\u0437","\u041a\u0430\u043a\u0438\u0435 \u0444\u0430\u0440\u0434\u044b (\u0441\u0442\u043e\u043b\u043f\u044b) \u0432\u043d\u0443\u0442\u0440\u0438 \u043d\u0430\u043c\u0430\u0437\u0430?","\u041d\u0430\u0447\u0430\u043b\u044c\u043d\u044b\u0439 \u0442\u0430\u043a\u0431\u0438\u0440, \u0441\u0442\u043e\u044f\u043d\u0438\u0435, \u0447\u0442\u0435\u043d\u0438\u0435 \u041a\u043e\u0440\u0430\u043d\u0430, \u043f\u043e\u044f\u0441\u043d\u043e\u0439 \u043f\u043e\u043a\u043b\u043e\u043d (\u0440\u0443\u043a\u0443), \u0434\u0432\u0430 \u0437\u0435\u043c\u043d\u044b\u0445 \u043f\u043e\u043a\u043b\u043e\u043d\u0430 (\u0441\u0443\u0434\u0436\u0443\u0434) \u0438 \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0435\u0435 \u0441\u0438\u0434\u0435\u043d\u0438\u0435 \u043d\u0430 \u0432\u0440\u0435\u043c\u044f \u0442\u0430\u0448\u0430\u0445\u0445\u0443\u0434\u0430.")
B.aj7=new A.q("\u041d\u0430\u043c\u0430\u0437","\u0427\u0442\u043e \u0442\u0430\u043a\u043e\u0435 \u0432\u0430\u0434\u0436\u0438\u0431\u044b \u043d\u0430\u043c\u0430\u0437\u0430?","\u041d\u0430\u043f\u0440\u0438\u043c\u0435\u0440: \u0447\u0442\u0435\u043d\u0438\u0435 \xab\u0430\u043b\u044c-\u0424\u0430\u0442\u0438\u0445\u0438\xbb \u0432 \u043a\u0430\u0436\u0434\u043e\u043c \u0440\u0430\u043a\u0430\u0430\u0442\u0435, \u0434\u043e\u0431\u0430\u0432\u043e\u0447\u043d\u0430\u044f \u0441\u0443\u0440\u0430 \u0432 \u043f\u0435\u0440\u0432\u044b\u0445 \u0434\u0432\u0443\u0445 \u0440\u0430\u043a\u0430\u0430\u0442\u0430\u0445 \u0444\u0430\u0440\u0434\u0430, \u043f\u0435\u0440\u0432\u043e\u0435 \u0441\u0438\u0434\u0435\u043d\u0438\u0435 \u0438 \u0442\u0430\u0448\u0430\u0445\u0445\u0443\u0434, \u0441\u043f\u043e\u043a\u043e\u0439\u0441\u0442\u0432\u0438\u0435 \u0432 \u043a\u0430\u0436\u0434\u043e\u043c \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0438, \u0441\u0430\u043b\u0430\u043c \u0432 \u043a\u043e\u043d\u0446\u0435, \u043a\u0443\u043d\u0443\u0442 \u0432 \u0432\u0438\u0442\u0440\u0435.")
B.ajp=new A.q("\u041d\u0430\u043c\u0430\u0437","\u0427\u0442\u043e \u0434\u0435\u043b\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u043f\u043e \u0437\u0430\u0431\u044b\u0432\u0447\u0438\u0432\u043e\u0441\u0442\u0438 \u043f\u0440\u043e\u043f\u0443\u0441\u0442\u0438\u043b \u0432\u0430\u0434\u0436\u0438\u0431?","\u0412 \u043a\u043e\u043d\u0446\u0435 \u043d\u0430\u043c\u0430\u0437\u0430 \u0441\u0434\u0435\u043b\u0430\u0442\u044c \u0441\u0430\u0434\u0436\u0434\u0430 \u0441\u0430\u0445\u0432: \u043f\u043e\u0441\u043b\u0435 \u0442\u0430\u0448\u0430\u0445\u0445\u0443\u0434\u0430 \u0434\u0430\u0442\u044c \u0441\u0430\u043b\u0430\u043c \u043d\u0430\u043f\u0440\u0430\u0432\u043e, \u0441\u043e\u0432\u0435\u0440\u0448\u0438\u0442\u044c \u0434\u0432\u0430 \u0437\u0435\u043c\u043d\u044b\u0445 \u043f\u043e\u043a\u043b\u043e\u043d\u0430, \u0441\u043d\u043e\u0432\u0430 \u043f\u0440\u043e\u0447\u0438\u0442\u0430\u0442\u044c \u0442\u0430\u0448\u0430\u0445\u0445\u0443\u0434, \u0441\u0430\u043b\u0430\u0432\u0430\u0442\u044b \u0438 \u0434\u0443\u0430, \u0437\u0430\u0442\u0435\u043c \u0441\u0430\u043b\u0430\u043c.")
B.alG=new A.q("\u041d\u0430\u043c\u0430\u0437","\u041a\u0430\u043a\u0438\u0435 \u0441\u0443\u043d\u043d\u044b-\u043c\u0443\u0430\u043a\u043a\u0430\u0434\u0430 \u043f\u0440\u0438 \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0445 \u043d\u0430\u043c\u0430\u0437\u0430\u0445?","2 \u0440\u0430\u043a\u0430\u0430\u0442\u0430 \u043f\u0435\u0440\u0435\u0434 \u0424\u0430\u0434\u0436\u0440\u043e\u043c, 4 \u043f\u0435\u0440\u0435\u0434 \u0417\u0443\u0445\u0440\u043e\u043c \u0438 2 \u043f\u043e\u0441\u043b\u0435 \u043d\u0435\u0433\u043e, 2 \u043f\u043e\u0441\u043b\u0435 \u041c\u0430\u0433\u0440\u0438\u0431\u0430, 2 \u043f\u043e\u0441\u043b\u0435 \u0418\u0448\u0438.")
B.ajH=new A.q("\u041d\u0430\u043c\u0430\u0437","\u0412\u0438\u0442\u0440 \u2014 \u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0440\u0430\u043a\u0430\u0430\u0442\u043e\u0432 \u0438 \u043a\u0430\u043a\u043e\u0439 \u0441\u0442\u0430\u0442\u0443\u0441?","3 \u0440\u0430\u043a\u0430\u0430\u0442\u0430 \u0441 \u043e\u0434\u043d\u0438\u043c \u0441\u0430\u043b\u0430\u043c\u043e\u043c. \u0423 \u0445\u0430\u043d\u0430\u0444\u0438\u0442\u043e\u0432 \u0432\u0438\u0442\u0440 \u2014 \u0432\u0430\u0434\u0436\u0438\u0431. \u0412 \u0442\u0440\u0435\u0442\u044c\u0435\u043c \u0440\u0430\u043a\u0430\u0430\u0442\u0435 \u043f\u0435\u0440\u0435\u0434 \u043f\u043e\u044f\u0441\u043d\u044b\u043c \u043f\u043e\u043a\u043b\u043e\u043d\u043e\u043c \u0447\u0438\u0442\u0430\u044e\u0442 \u0434\u0443\u0430 \u043a\u0443\u043d\u0443\u0442. \u0412\u0440\u0435\u043c\u044f \u2014 \u043f\u043e\u0441\u043b\u0435 \u0418\u0448\u0438 \u0434\u043e \u0440\u0430\u0441\u0441\u0432\u0435\u0442\u0430.")
B.aja=new A.q("\u041d\u0430\u043c\u0430\u0437","\u0427\u0442\u043e \u0434\u0435\u043b\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u043f\u0440\u043e\u043f\u0443\u0441\u0442\u0438\u043b \u043d\u0430\u043c\u0430\u0437?","\u0412\u043e\u0441\u043f\u043e\u043b\u043d\u0438\u0442\u044c \u0435\u0433\u043e (\u043a\u0430\u0437\u0430) \u043a\u0430\u043a \u043c\u043e\u0436\u043d\u043e \u0441\u043a\u043e\u0440\u0435\u0435 \u0438 \u043f\u043e\u043a\u0430\u044f\u0442\u044c\u0441\u044f. \u0411\u0435\u0437 \u0443\u0432\u0430\u0436\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0439 \u043f\u0440\u0438\u0447\u0438\u043d\u044b \u043f\u0440\u043e\u043f\u0443\u0441\u043a\u0430\u0442\u044c \u043d\u0430\u043c\u0430\u0437 \u2014 \u0431\u043e\u043b\u044c\u0448\u043e\u0439 \u0433\u0440\u0435\u0445.")
B.aiD=new A.q("\u041d\u0430\u043c\u0430\u0437","\u041a\u0430\u043a\u043e\u0432 \u0430\u0443\u0440\u0430\u0442 \u043c\u0443\u0436\u0447\u0438\u043d\u044b \u0432 \u043d\u0430\u043c\u0430\u0437\u0435?","\u041e\u0442 \u043f\u0443\u043f\u043a\u0430 \u0434\u043e \u043a\u043e\u043b\u0435\u043d, \u043a\u043e\u043b\u0435\u043d\u043e \u0432\u0445\u043e\u0434\u0438\u0442 \u0432 \u0430\u0443\u0440\u0430\u0442.")
B.aih=new A.q("\u041d\u0430\u043c\u0430\u0437","\u041a\u0430\u043a\u043e\u0432 \u0430\u0443\u0440\u0430\u0442 \u0436\u0435\u043d\u0449\u0438\u043d\u044b \u0432 \u043d\u0430\u043c\u0430\u0437\u0435?","\u0412\u0441\u0451 \u0442\u0435\u043b\u043e, \u043a\u0440\u043e\u043c\u0435 \u043b\u0438\u0446\u0430, \u043a\u0438\u0441\u0442\u0435\u0439 \u0440\u0443\u043a \u0438 \u0441\u0442\u043e\u043f.")
B.am_=new A.q("\u041d\u0430\u043c\u0430\u0437","\u041a\u0430\u043a \u0441\u043e\u0432\u0435\u0440\u0448\u0430\u0435\u0442 \u043d\u0430\u043c\u0430\u0437 \u043f\u0443\u0442\u043d\u0438\u043a (\u043c\u0443\u0441\u0430\u0444\u0438\u0440)?","\u0415\u0441\u043b\u0438 \u0447\u0435\u043b\u043e\u0432\u0435\u043a \u0432\u044b\u0435\u0445\u0430\u043b \u043d\u0430 \u0440\u0430\u0441\u0441\u0442\u043e\u044f\u043d\u0438\u0435 \u043e\u043a\u043e\u043b\u043e 90 \u043a\u043c \u0438 \u0441\u043e\u0431\u0438\u0440\u0430\u0435\u0442\u0441\u044f \u043f\u0440\u043e\u0431\u044b\u0442\u044c \u0432 \u043c\u0435\u0441\u0442\u0435 \u043c\u0435\u043d\u044c\u0448\u0435 15 \u0434\u043d\u0435\u0439, \u0447\u0435\u0442\u044b\u0440\u0451\u0445\u0440\u0430\u043a\u0430\u0430\u0442\u043d\u044b\u0435 \u0444\u0430\u0440\u0434\u044b \u043e\u043d \u0441\u043e\u043a\u0440\u0430\u0449\u0430\u0435\u0442 \u0434\u043e \u0434\u0432\u0443\u0445. \u0423 \u0445\u0430\u043d\u0430\u0444\u0438\u0442\u043e\u0432 \u0441\u043e\u043a\u0440\u0430\u0449\u0435\u043d\u0438\u0435 \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u043e.")
B.ajM=new A.q("\u041d\u0430\u043c\u0430\u0437","\u041c\u043e\u0436\u043d\u043e \u043b\u0438 \u043e\u0431\u044a\u0435\u0434\u0438\u043d\u044f\u0442\u044c \u0434\u0432\u0430 \u043d\u0430\u043c\u0430\u0437\u0430 \u0432 \u043e\u0434\u043d\u043e \u0432\u0440\u0435\u043c\u044f?","\u041f\u043e \u0445\u0430\u043d\u0430\u0444\u0438\u0442\u0441\u043a\u043e\u043c\u0443 \u043c\u0430\u0437\u0445\u0430\u0431\u0443 \u2014 \u043d\u0435\u0442, \u043a\u0430\u0436\u0434\u044b\u0439 \u043d\u0430\u043c\u0430\u0437 \u0441\u043e\u0432\u0435\u0440\u0448\u0430\u044e\u0442 \u0432 \u0435\u0433\u043e \u0432\u0440\u0435\u043c\u044f. \u0418\u0441\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u0435 \u2014 \u0410\u0440\u0430\u0444\u0430\u0442 \u0438 \u041c\u0443\u0437\u0434\u0430\u043b\u0438\u0444\u0430 \u0432\u043e \u0432\u0440\u0435\u043c\u044f \u0445\u0430\u0434\u0436\u0430.")
B.ai0=new A.q("\u041d\u0430\u043c\u0430\u0437","\u0414\u043b\u044f \u043a\u043e\u0433\u043e \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u0435\u043d \u043f\u044f\u0442\u043d\u0438\u0447\u043d\u044b\u0439 \u043d\u0430\u043c\u0430\u0437 (\u0434\u0436\u0443\u043c\u0430)?","\u0414\u043b\u044f \u0441\u0432\u043e\u0431\u043e\u0434\u043d\u043e\u0433\u043e, \u0437\u0434\u043e\u0440\u043e\u0432\u043e\u0433\u043e, \u0441\u043e\u0432\u0435\u0440\u0448\u0435\u043d\u043d\u043e\u043b\u0435\u0442\u043d\u0435\u0433\u043e \u043c\u0443\u0436\u0447\u0438\u043d\u044b, \u0436\u0438\u0432\u0443\u0449\u0435\u0433\u043e \u0432 \u0433\u043e\u0440\u043e\u0434\u0435. \u0414\u0436\u0443\u043c\u0430 \u0441\u043e\u0432\u0435\u0440\u0448\u0430\u0435\u0442\u0441\u044f \u0432\u043c\u0435\u0441\u0442\u043e \u0417\u0443\u0445\u0440\u0430. \u0416\u0435\u043d\u0449\u0438\u043d\u0430\u043c \u0438 \u043f\u0443\u0442\u043d\u0438\u043a\u0430\u043c \u043d\u0435 \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u0430, \u043d\u043e \u0435\u0441\u043b\u0438 \u043f\u0440\u0438\u0434\u0443\u0442 \u2014 \u043e\u043d\u0430 \u0437\u0430\u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044f.")
B.ajz=new A.q("\u041d\u0430\u043c\u0430\u0437","\u0427\u0438\u0442\u0430\u0435\u0442 \u043b\u0438 \xab\u0424\u0430\u0442\u0438\u0445\u0443\xbb \u0442\u043e\u0442, \u043a\u0442\u043e \u043c\u043e\u043b\u0438\u0442\u0441\u044f \u0437\u0430 \u0438\u043c\u0430\u043c\u043e\u043c?","\u0423 \u0445\u0430\u043d\u0430\u0444\u0438\u0442\u043e\u0432 \u043f\u043e\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044c \u0437\u0430 \u0438\u043c\u0430\u043c\u043e\u043c \u043d\u0435 \u0447\u0438\u0442\u0430\u0435\u0442, \u0430 \u043c\u043e\u043b\u0447\u0430 \u0441\u043b\u0443\u0448\u0430\u0435\u0442: \u0447\u0442\u0435\u043d\u0438\u0435 \u0438\u043c\u0430\u043c\u0430 \u2014 \u0447\u0442\u0435\u043d\u0438\u0435 \u0438 \u0434\u043b\u044f \u043d\u0435\u0433\u043e.")
B.amS=new A.q("\u041d\u0430\u043c\u0430\u0437","\u0427\u0442\u043e \u043d\u0430\u0440\u0443\u0448\u0430\u0435\u0442 \u043d\u0430\u043c\u0430\u0437?","\u0420\u0430\u0437\u0433\u043e\u0432\u043e\u0440, \u0435\u0434\u0430 \u0438 \u043f\u0438\u0442\u044c\u0451, \u043c\u043d\u043e\u0433\u043e \u043f\u043e\u0441\u0442\u043e\u0440\u043e\u043d\u043d\u0438\u0445 \u0434\u0432\u0438\u0436\u0435\u043d\u0438\u0439, \u043f\u043e\u0432\u043e\u0440\u043e\u0442 \u0433\u0440\u0443\u0434\u0438 \u043e\u0442 \u043a\u0438\u0431\u043b\u044b, \u0433\u0440\u043e\u043c\u043a\u0438\u0439 \u0441\u043c\u0435\u0445, \u043d\u0430\u0440\u0443\u0448\u0435\u043d\u0438\u0435 \u043e\u043c\u043e\u0432\u0435\u043d\u0438\u044f, \u043e\u0442\u043a\u0440\u044b\u0442\u0438\u0435 \u0430\u0443\u0440\u0430\u0442\u0430 \u043d\u0430 \u0432\u0440\u0435\u043c\u044f \u043e\u0434\u043d\u043e\u0433\u043e \u0441\u0442\u043e\u043b\u043f\u0430.")
B.aj_=new A.q("\u041d\u0430\u043c\u0430\u0437","\u0412 \u043a\u0430\u043a\u043e\u0435 \u0432\u0440\u0435\u043c\u044f \u043d\u0430\u043c\u0430\u0437 \u0437\u0430\u043f\u0440\u0435\u0449\u0451\u043d?","\u0412\u043e \u0432\u0440\u0435\u043c\u044f \u0432\u043e\u0441\u0445\u043e\u0434\u0430 \u0441\u043e\u043b\u043d\u0446\u0430, \u043a\u043e\u0433\u0434\u0430 \u0441\u043e\u043b\u043d\u0446\u0435 \u0432 \u0437\u0435\u043d\u0438\u0442\u0435 \u0438 \u0432\u043e \u0432\u0440\u0435\u043c\u044f \u0437\u0430\u043a\u0430\u0442\u0430. \u041f\u043e\u0441\u043b\u0435 \u0443\u0442\u0440\u0435\u043d\u043d\u0435\u0433\u043e \u0444\u0430\u0440\u0434\u0430 \u0434\u043e \u0432\u043e\u0441\u0445\u043e\u0434\u0430 \u0438 \u043f\u043e\u0441\u043b\u0435 \u0410\u0441\u0440\u0430 \u0434\u043e \u0437\u0430\u043a\u0430\u0442\u0430 \u043d\u0435\u0436\u0435\u043b\u0430\u0442\u0435\u043b\u044c\u043d\u043e \u0441\u043e\u0432\u0435\u0440\u0448\u0430\u0442\u044c \u0434\u043e\u0431\u0440\u043e\u0432\u043e\u043b\u044c\u043d\u044b\u0435 \u043d\u0430\u043c\u0430\u0437\u044b.")
B.ajm=new A.q("\u041d\u0430\u043c\u0430\u0437","\u0427\u0442\u043e \u0442\u0430\u043a\u043e\u0435 \u0441\u0430\u0434\u0436\u0434\u0430 \u0442\u0438\u043b\u044f\u0432\u0430\u0442?","\u0417\u0435\u043c\u043d\u043e\u0439 \u043f\u043e\u043a\u043b\u043e\u043d \u043f\u0440\u0438 \u0447\u0442\u0435\u043d\u0438\u0438 \u0438\u043b\u0438 \u0441\u043b\u0443\u0448\u0430\u043d\u0438\u0438 \u0430\u044f\u0442\u0430, \u0433\u0434\u0435 \u0435\u0441\u0442\u044c \u043f\u043e\u043a\u043b\u043e\u043d (\u0432 \u041a\u043e\u0440\u0430\u043d\u0435 \u0438\u0445 14). \u0423 \u0445\u0430\u043d\u0430\u0444\u0438\u0442\u043e\u0432 \u043e\u043d \u0432\u0430\u0434\u0436\u0438\u0431.")
B.alv=new A.q("\u041d\u0430\u043c\u0430\u0437","\u0427\u0442\u043e \u0434\u0435\u043b\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u0441\u043e\u043c\u043d\u0435\u0432\u0430\u0435\u0448\u044c\u0441\u044f \u0432 \u0447\u0438\u0441\u043b\u0435 \u0440\u0430\u043a\u0430\u0430\u0442\u043e\u0432?","\u0415\u0441\u043b\u0438 \u0442\u0430\u043a\u043e\u0435 \u0441\u043e\u043c\u043d\u0435\u043d\u0438\u0435 \u0432\u043f\u0435\u0440\u0432\u044b\u0435 \u2014 \u043d\u0430\u0447\u0430\u0442\u044c \u043d\u0430\u043c\u0430\u0437 \u0437\u0430\u043d\u043e\u0432\u043e. \u0415\u0441\u043b\u0438 \u0431\u044b\u0432\u0430\u0435\u0442 \u0447\u0430\u0441\u0442\u043e \u2014 \u043e\u043f\u0438\u0440\u0430\u0442\u044c\u0441\u044f \u043d\u0430 \u0442\u043e, \u0447\u0442\u043e \u043a\u0430\u0436\u0435\u0442\u0441\u044f \u0432\u0435\u0440\u043d\u0435\u0435, \u0430 \u0435\u0441\u043b\u0438 \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u043f\u0435\u0440\u0435\u0432\u0435\u0448\u0438\u0432\u0430\u0435\u0442 \u2014 \u043d\u0430 \u043c\u0435\u043d\u044c\u0448\u0435\u0435 \u0447\u0438\u0441\u043b\u043e, \u0438 \u0432 \u043a\u043e\u043d\u0446\u0435 \u0441\u0434\u0435\u043b\u0430\u0442\u044c \u0441\u0430\u0434\u0436\u0434\u0430 \u0441\u0430\u0445\u0432.")
B.alA=new A.q("\u041d\u0430\u043c\u0430\u0437","\u041a\u0430\u043a \u0441\u043e\u0432\u0435\u0440\u0448\u0430\u044e\u0442 \u043f\u0440\u0430\u0437\u0434\u043d\u0438\u0447\u043d\u044b\u0439 \u043d\u0430\u043c\u0430\u0437 (\u0418\u0434)?","\u0423 \u0445\u0430\u043d\u0430\u0444\u0438\u0442\u043e\u0432 \u043e\u043d \u0432\u0430\u0434\u0436\u0438\u0431: 2 \u0440\u0430\u043a\u0430\u0430\u0442\u0430 \u0431\u0435\u0437 \u0430\u0437\u0430\u043d\u0430 \u0438 \u0438\u043a\u0430\u043c\u0430\u0442\u0430, \u0441 \u0442\u0440\u0435\u043c\u044f \u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u043c\u0438 \u0442\u0430\u043a\u0431\u0438\u0440\u0430\u043c\u0438 \u0432 \u043a\u0430\u0436\u0434\u043e\u043c \u0440\u0430\u043a\u0430\u0430\u0442\u0435. \u041f\u043e\u0441\u043b\u0435 \u043d\u0430\u043c\u0430\u0437\u0430 \u2014 \u043f\u0440\u043e\u043f\u043e\u0432\u0435\u0434\u044c (\u0445\u0443\u0442\u0431\u0430).")
B.aiU=new A.q("\u041d\u0430\u043c\u0430\u0437","\u041a\u0430\u043a \u0441\u043e\u0432\u0435\u0440\u0448\u0430\u044e\u0442 \u0434\u0436\u0430\u043d\u0430\u0437\u0430-\u043d\u0430\u043c\u0430\u0437?","\u0421\u0442\u043e\u044f, \u0441 \u0447\u0435\u0442\u044b\u0440\u044c\u043c\u044f \u0442\u0430\u043a\u0431\u0438\u0440\u0430\u043c\u0438, \u0431\u0435\u0437 \u043f\u043e\u044f\u0441\u043d\u044b\u0445 \u0438 \u0437\u0435\u043c\u043d\u044b\u0445 \u043f\u043e\u043a\u043b\u043e\u043d\u043e\u0432: \u043f\u043e\u0441\u043b\u0435 \u043f\u0435\u0440\u0432\u043e\u0433\u043e \u2014 \u0441\u0430\u043d\u0430, \u043f\u043e\u0441\u043b\u0435 \u0432\u0442\u043e\u0440\u043e\u0433\u043e \u2014 \u0441\u0430\u043b\u0430\u0432\u0430\u0442, \u043f\u043e\u0441\u043b\u0435 \u0442\u0440\u0435\u0442\u044c\u0435\u0433\u043e \u2014 \u0434\u0443\u0430 \u0437\u0430 \u0443\u043c\u0435\u0440\u0448\u0435\u0433\u043e, \u043f\u043e\u0441\u043b\u0435 \u0447\u0435\u0442\u0432\u0451\u0440\u0442\u043e\u0433\u043e \u2014 \u0441\u0430\u043b\u0430\u043c. \u042d\u0442\u043e \u0444\u0430\u0440\u0434 \u043a\u0438\u0444\u0430\u044f.")
B.aje=new A.q("\u041d\u0430\u043c\u0430\u0437","\u0427\u0442\u043e \u0442\u0430\u043a\u043e\u0435 \u0442\u0430\u0440\u0430\u0432\u0438\u0445?","\u0421\u0443\u043d\u043d\u0430 \u043c\u0443\u0430\u043a\u043a\u0430\u0434\u0430 \u0432 \u043d\u043e\u0447\u0438 \u0420\u0430\u043c\u0430\u0434\u0430\u043d\u0430 \u043f\u043e\u0441\u043b\u0435 \u0418\u0448\u0438: 20 \u0440\u0430\u043a\u0430\u0430\u0442\u043e\u0432 \u043f\u043e \u0434\u0432\u0430, \u0441 \u043e\u0442\u0434\u044b\u0445\u043e\u043c \u043f\u043e\u0441\u043b\u0435 \u043a\u0430\u0436\u0434\u044b\u0445 \u0447\u0435\u0442\u044b\u0440\u0451\u0445.")
B.am8=new A.q("\u041d\u0430\u043c\u0430\u0437","\u0421\u043e\u0432\u0435\u0440\u0448\u0430\u0435\u0442 \u043b\u0438 \u043d\u0430\u043c\u0430\u0437 \u0436\u0435\u043d\u0449\u0438\u043d\u0430 \u0432\u043e \u0432\u0440\u0435\u043c\u044f \u043c\u0435\u0441\u044f\u0447\u043d\u044b\u0445?","\u041d\u0435\u0442. \u041d\u0430\u043c\u0430\u0437\u044b \u044d\u0442\u043e\u0433\u043e \u0432\u0440\u0435\u043c\u0435\u043d\u0438 \u043d\u0435 \u0441\u043e\u0432\u0435\u0440\u0448\u0430\u044e\u0442 \u0438 \u043f\u043e\u0442\u043e\u043c \u043d\u0435 \u0432\u043e\u0441\u043f\u043e\u043b\u043d\u044f\u044e\u0442. \u041f\u0440\u043e\u043f\u0443\u0449\u0435\u043d\u043d\u044b\u0435 \u0434\u043d\u0438 \u043f\u043e\u0441\u0442\u0430 \u0432\u043e\u0441\u043f\u043e\u043b\u043d\u044f\u044e\u0442.")
B.aiC=new A.q("\u041f\u043e\u0441\u0442","\u041a\u043e\u0433\u0434\u0430 \u0434\u0435\u043b\u0430\u0442\u044c \u043d\u0430\u043c\u0435\u0440\u0435\u043d\u0438\u0435 \u043d\u0430 \u043f\u043e\u0441\u0442 \u0420\u0430\u043c\u0430\u0434\u0430\u043d\u0430?","\u041b\u0443\u0447\u0448\u0435 \u043d\u043e\u0447\u044c\u044e, \u0434\u043e \u0440\u0430\u0441\u0441\u0432\u0435\u0442\u0430. \u0414\u043b\u044f \u043f\u043e\u0441\u0442\u0430 \u0420\u0430\u043c\u0430\u0434\u0430\u043d\u0430 \u0434\u043e\u043f\u0443\u0441\u0442\u0438\u043c\u043e \u0438 \u0434\u043d\u0451\u043c \u2014 \u0434\u043e \u0441\u0435\u0440\u0435\u0434\u0438\u043d\u044b \u0448\u0430\u0440\u0438\u0430\u0442\u0441\u043a\u043e\u0433\u043e \u0434\u043d\u044f, \u0435\u0441\u043b\u0438 \u0435\u0449\u0451 \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0435\u043b.")
B.aj4=new A.q("\u041f\u043e\u0441\u0442","\u0427\u0442\u043e \u043d\u0430\u0440\u0443\u0448\u0430\u0435\u0442 \u043f\u043e\u0441\u0442 \u0438 \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u043a\u0430\u0437\u0430 (\u043e\u0434\u043d\u043e\u0433\u043e \u0434\u043d\u044f)?","\u041d\u0430\u043f\u0440\u0438\u043c\u0435\u0440: \u0441\u043b\u0443\u0447\u0430\u0439\u043d\u043e \u043f\u0440\u043e\u0433\u043b\u043e\u0447\u0435\u043d\u043d\u0430\u044f \u043f\u0440\u0438 \u043f\u043e\u043b\u043e\u0441\u043a\u0430\u043d\u0438\u0438 \u0432\u043e\u0434\u0430, \u043d\u0430\u043c\u0435\u0440\u0435\u043d\u043d\u0430\u044f \u0440\u0432\u043e\u0442\u0430 \u043f\u043e\u043b\u043d\u044b\u043c \u0440\u0442\u043e\u043c, \u0435\u0434\u0430, \u043a\u043e\u0433\u0434\u0430 \u0434\u0443\u043c\u0430\u043b, \u0447\u0442\u043e \u0435\u0449\u0451 \u043d\u043e\u0447\u044c, \u0430 \u0440\u0430\u0441\u0441\u0432\u0435\u0442 \u0443\u0436\u0435 \u043d\u0430\u0441\u0442\u0443\u043f\u0438\u043b.")
B.amP=new A.q("\u041f\u043e\u0441\u0442","\u0417\u0430 \u0447\u0442\u043e \u043f\u043e\u043b\u043e\u0436\u0435\u043d\u0430 \u043a\u0430\u0444\u0444\u0430\u0440\u0430?","\u0417\u0430 \u043d\u0430\u043c\u0435\u0440\u0435\u043d\u043d\u0443\u044e \u0435\u0434\u0443, \u043f\u0438\u0442\u044c\u0451 \u0438\u043b\u0438 \u0431\u043b\u0438\u0437\u043e\u0441\u0442\u044c \u0434\u043d\u0451\u043c \u0432 \u0420\u0430\u043c\u0430\u0434\u0430\u043d \u0431\u0435\u0437 \u0443\u0432\u0430\u0436\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0439 \u043f\u0440\u0438\u0447\u0438\u043d\u044b. \u041a\u0430\u0444\u0444\u0430\u0440\u0430 \u2014 60 \u0434\u043d\u0435\u0439 \u043f\u043e\u0441\u0442\u0430 \u043f\u043e\u0434\u0440\u044f\u0434 (\u0435\u0441\u043b\u0438 \u043d\u0435 \u043c\u043e\u0436\u0435\u0442 \u2014 \u043d\u0430\u043a\u043e\u0440\u043c\u0438\u0442\u044c 60 \u0431\u0435\u0434\u043d\u044b\u0445), \u043f\u043b\u044e\u0441 \u0432\u043e\u0441\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u044d\u0442\u043e\u0433\u043e \u0434\u043d\u044f.")
B.amv=new A.q("\u041f\u043e\u0441\u0442","\u0427\u0442\u043e \u0442\u0430\u043a\u043e\u0435 \u0441\u0443\u0445\u0443\u0440 \u0438 \u0438\u0444\u0442\u0430\u0440?","\u0421\u0443\u0445\u0443\u0440 \u2014 \u0435\u0434\u0430 \u0434\u043e \u0440\u0430\u0441\u0441\u0432\u0435\u0442\u0430, \u044d\u0442\u043e \u0441\u0443\u043d\u043d\u0430, \u0435\u0451 \u043b\u0443\u0447\u0448\u0435 \u043e\u0442\u043a\u043b\u0430\u0434\u044b\u0432\u0430\u0442\u044c. \u0418\u0444\u0442\u0430\u0440 \u2014 \u0440\u0430\u0437\u0433\u043e\u0432\u0435\u043d\u0438\u0435 \u0441\u0440\u0430\u0437\u0443 \u043f\u043e\u0441\u043b\u0435 \u0437\u0430\u043a\u0430\u0442\u0430, \u0441\u043f\u0435\u0448\u0438\u0442\u044c \u0441 \u043d\u0438\u043c \u2014 \u0441\u0443\u043d\u043d\u0430.")
B.ahS=new A.q("\u041f\u043e\u0441\u0442","\u041a\u043e\u043c\u0443 \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043d\u043e \u043d\u0435 \u043f\u043e\u0441\u0442\u0438\u0442\u044c\u0441\u044f \u0432 \u0420\u0430\u043c\u0430\u0434\u0430\u043d?","\u0411\u043e\u043b\u044c\u043d\u043e\u043c\u0443, \u043f\u0443\u0442\u043d\u0438\u043a\u0443, \u0431\u0435\u0440\u0435\u043c\u0435\u043d\u043d\u043e\u0439 \u0438\u043b\u0438 \u043a\u043e\u0440\u043c\u044f\u0449\u0435\u0439 \u043f\u0440\u0438 \u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u0438 \u0434\u043b\u044f \u043d\u0435\u0451 \u0438\u043b\u0438 \u0440\u0435\u0431\u0451\u043d\u043a\u0430 \u2014 \u043e\u043d\u0438 \u043f\u043e\u0442\u043e\u043c \u0432\u043e\u0441\u043f\u043e\u043b\u043d\u044f\u044e\u0442. \u041f\u043e\u0436\u0438\u043b\u043e\u0439, \u043a\u0442\u043e \u043d\u0435 \u043c\u043e\u0436\u0435\u0442 \u0434\u0435\u0440\u0436\u0430\u0442\u044c \u043f\u043e\u0441\u0442, \u043f\u043b\u0430\u0442\u0438\u0442 \u0444\u0438\u0434\u044c\u044e \u0437\u0430 \u043a\u0430\u0436\u0434\u044b\u0439 \u0434\u0435\u043d\u044c.")
B.aiI=new A.q("\u041f\u043e\u0441\u0442","\u041d\u0430\u0440\u0443\u0448\u0430\u044e\u0442 \u043b\u0438 \u043f\u043e\u0441\u0442 \u043c\u0438\u0441\u0432\u0430\u043a \u0438 \u0437\u0443\u0431\u043d\u0430\u044f \u043f\u0430\u0441\u0442\u0430?","\u041c\u0438\u0441\u0432\u0430\u043a \u2014 \u0441\u0443\u043d\u043d\u0430 \u0438 \u043f\u043e\u0441\u0442 \u043d\u0435 \u043d\u0430\u0440\u0443\u0448\u0430\u0435\u0442. \u041f\u0430\u0441\u0442\u0443 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u044c \u043d\u0435\u0436\u0435\u043b\u0430\u0442\u0435\u043b\u044c\u043d\u043e, \u043d\u043e \u0435\u0441\u043b\u0438 \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u043f\u0440\u043e\u0433\u043b\u043e\u0447\u0435\u043d\u043e \u2014 \u043f\u043e\u0441\u0442 \u043d\u0435 \u043d\u0430\u0440\u0443\u0448\u0435\u043d.")
B.akb=new A.q("\u041f\u043e\u0441\u0442","\u0427\u0442\u043e \u0442\u0430\u043a\u043e\u0435 \u0437\u0430\u043a\u044f\u0442 \u0430\u043b\u044c-\u0444\u0438\u0442\u0440 (\u0444\u0438\u0442\u0440-\u0441\u0430\u0434\u0430\u043a\u0430)?","\u0412\u0430\u0434\u0436\u0438\u0431 \u0434\u043b\u044f \u043c\u0443\u0441\u0443\u043b\u044c\u043c\u0430\u043d\u0438\u043d\u0430, \u0443 \u043a\u043e\u0442\u043e\u0440\u043e\u0433\u043e \u0435\u0441\u0442\u044c \u043d\u0438\u0441\u0430\u0431: \u0437\u0430 \u0441\u0435\u0431\u044f \u0438 \u0437\u0430 \u043c\u0430\u043b\u043e\u043b\u0435\u0442\u043d\u0438\u0445 \u0434\u0435\u0442\u0435\u0439. \u041e\u0442\u0434\u0430\u044e\u0442 \u0434\u043e \u043f\u0440\u0430\u0437\u0434\u043d\u0438\u0447\u043d\u043e\u0433\u043e \u043d\u0430\u043c\u0430\u0437\u0430 \u0418\u0434 \u0430\u043b\u044c-\u0424\u0438\u0442\u0440. \u0420\u0430\u0437\u043c\u0435\u0440 \u043a\u0430\u0436\u0434\u044b\u0439 \u0433\u043e\u0434 \u043e\u0431\u044a\u044f\u0432\u043b\u044f\u0435\u0442 \u0414\u0423\u041c\u041a.")
B.aij=new A.q("\u0417\u0430\u043a\u044f\u0442","\u0427\u0442\u043e \u0442\u0430\u043a\u043e\u0435 \u043d\u0438\u0441\u0430\u0431?","\u041d\u0430\u0438\u043c\u0435\u043d\u044c\u0448\u0435\u0435 \u0431\u043e\u0433\u0430\u0442\u0441\u0442\u0432\u043e, \u0441 \u043a\u043e\u0442\u043e\u0440\u043e\u0433\u043e \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u0435\u043d \u0437\u0430\u043a\u044f\u0442: \u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c 85 \u0433 \u0437\u043e\u043b\u043e\u0442\u0430 \u0438\u043b\u0438 595 \u0433 \u0441\u0435\u0440\u0435\u0431\u0440\u0430. \u0421\u0443\u043c\u043c\u0443 \u043d\u0438\u0441\u0430\u0431\u0430 \u0432 \u0442\u0435\u043d\u0433\u0435 \u043a\u0430\u0436\u0434\u044b\u0439 \u0433\u043e\u0434 \u043e\u0431\u044a\u044f\u0432\u043b\u044f\u0435\u0442 \u0414\u0423\u041c\u041a.")
B.aki=new A.q("\u0417\u0430\u043a\u044f\u0442","\u0421 \u043a\u0430\u043a\u043e\u0433\u043e \u0438\u043c\u0443\u0449\u0435\u0441\u0442\u0432\u0430 \u043f\u043b\u0430\u0442\u044f\u0442 \u0437\u0430\u043a\u044f\u0442?","\u0421 \u0434\u0435\u043d\u0435\u0433, \u0437\u043e\u043b\u043e\u0442\u0430 \u0438 \u0441\u0435\u0440\u0435\u0431\u0440\u0430, \u0442\u043e\u0432\u0430\u0440\u043e\u0432 \u0434\u043b\u044f \u0442\u043e\u0440\u0433\u043e\u0432\u043b\u0438 \u0438 \u0441\u043e \u0441\u043a\u043e\u0442\u0430 (\u043f\u0440\u0438 \u0443\u0441\u043b\u043e\u0432\u0438\u044f\u0445). \u0418\u043c\u0443\u0449\u0435\u0441\u0442\u0432\u043e \u0434\u043e\u043b\u0436\u043d\u043e \u0431\u044b\u0442\u044c \u0441\u0432\u0435\u0440\u0445 \u043e\u0441\u043d\u043e\u0432\u043d\u044b\u0445 \u043d\u0443\u0436\u0434 \u0438 \u043f\u0440\u043e\u0431\u044b\u0442\u044c \u0443 \u0442\u0435\u0431\u044f \u043b\u0443\u043d\u043d\u044b\u0439 \u0433\u043e\u0434.")
B.akm=new A.q("\u0417\u0430\u043a\u044f\u0442","\u041f\u043b\u0430\u0442\u044f\u0442 \u043b\u0438 \u0437\u0430\u043a\u044f\u0442 \u0441 \u0436\u0438\u043b\u044c\u044f \u0438 \u043c\u0430\u0448\u0438\u043d\u044b?","\u041d\u0435\u0442. \u0412\u0435\u0449\u0438 \u0434\u043b\u044f \u043b\u0438\u0447\u043d\u043e\u0433\u043e \u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u044f \u2014 \u0434\u043e\u043c, \u0433\u0434\u0435 \u0436\u0438\u0432\u0451\u0448\u044c, \u043c\u0430\u0448\u0438\u043d\u0430, \u043e\u0434\u0435\u0436\u0434\u0430, \u043c\u0435\u0431\u0435\u043b\u044c \u2014 \u0437\u0430\u043a\u044f\u0442\u043e\u043c \u043d\u0435 \u043e\u0431\u043b\u0430\u0433\u0430\u044e\u0442\u0441\u044f.")
B.amq=new A.q("\u0417\u0430\u043a\u044f\u0442","\u041a\u043e\u043c\u0443 \u043d\u0435\u043b\u044c\u0437\u044f \u043e\u0442\u0434\u0430\u0432\u0430\u0442\u044c \u0437\u0430\u043a\u044f\u0442?","\u0421\u0432\u043e\u0438\u043c \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044f\u043c, \u0434\u0435\u0434\u0443\u0448\u043a\u0430\u043c \u0438 \u0431\u0430\u0431\u0443\u0448\u043a\u0430\u043c, \u0434\u0435\u0442\u044f\u043c \u0438 \u0432\u043d\u0443\u043a\u0430\u043c, \u0441\u0443\u043f\u0440\u0443\u0433\u0443 \u0438\u043b\u0438 \u0441\u0443\u043f\u0440\u0443\u0433\u0435, \u0431\u043e\u0433\u0430\u0442\u043e\u043c\u0443 \u0447\u0435\u043b\u043e\u0432\u0435\u043a\u0443. \u041d\u0435\u043b\u044c\u0437\u044f \u043e\u0442\u0434\u0430\u0432\u0430\u0442\u044c \u0437\u0430\u043a\u044f\u0442 \u043d\u0430 \u0441\u0442\u0440\u043e\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u043c\u0435\u0447\u0435\u0442\u0438 \u2014 \u0437\u0430\u043a\u044f\u0442 \u0434\u043e\u043b\u0436\u0435\u043d \u043f\u0435\u0440\u0435\u0439\u0442\u0438 \u0432 \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0441\u0442\u044c \u043d\u0443\u0436\u0434\u0430\u044e\u0449\u0435\u0433\u043e\u0441\u044f.")
B.amB=new A.q("\u0425\u0430\u0434\u0436","\u041a\u043e\u043c\u0443 \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u0435\u043d \u0445\u0430\u0434\u0436?","\u0421\u043e\u0432\u0435\u0440\u0448\u0435\u043d\u043d\u043e\u043b\u0435\u0442\u043d\u0435\u043c\u0443, \u0440\u0430\u0437\u0443\u043c\u043d\u043e\u043c\u0443 \u043c\u0443\u0441\u0443\u043b\u044c\u043c\u0430\u043d\u0438\u043d\u0443, \u0443 \u043a\u043e\u0442\u043e\u0440\u043e\u0433\u043e \u0435\u0441\u0442\u044c \u0441\u0440\u0435\u0434\u0441\u0442\u0432\u0430 \u0438 \u0437\u0434\u043e\u0440\u043e\u0432\u044c\u0435, \u2014 \u043e\u0434\u0438\u043d \u0440\u0430\u0437 \u0432 \u0436\u0438\u0437\u043d\u0438. \u0416\u0435\u043d\u0449\u0438\u043d\u0430 \u043e\u0442\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u0441 \u043c\u0430\u0445\u0440\u0430\u043c\u043e\u043c.")
B.ahQ=new A.q("\u0425\u0430\u0434\u0436","\u041a\u0430\u043a\u0438\u0435 \u0444\u0430\u0440\u0434\u044b \u0443 \u0445\u0430\u0434\u0436\u0430?","\u0418\u0445\u0440\u0430\u043c, \u0441\u0442\u043e\u044f\u043d\u0438\u0435 \u043d\u0430 \u0410\u0440\u0430\u0444\u0430\u0442\u0435 9 \u0437\u0443\u043b\u044c-\u0445\u0438\u0434\u0436\u0430 \u0438 \u0442\u0430\u0432\u0430\u0444-\u0437\u0438\u044f\u0440\u0430\u0442.")
B.amj=new A.q("\u0425\u0430\u0434\u0436","\u0427\u0442\u043e \u0442\u0430\u043a\u043e\u0435 \u0443\u043c\u0440\u0430?","\xab\u041c\u0430\u043b\u044b\u0439 \u0445\u0430\u0434\u0436\xbb, \u0435\u0433\u043e \u043c\u043e\u0436\u043d\u043e \u0441\u043e\u0432\u0435\u0440\u0448\u0430\u0442\u044c \u0432 \u043b\u044e\u0431\u043e\u0435 \u0432\u0440\u0435\u043c\u044f \u0433\u043e\u0434\u0430: \u0438\u0445\u0440\u0430\u043c, \u0442\u0430\u0432\u0430\u0444 \u0432\u043e\u043a\u0440\u0443\u0433 \u041a\u0430\u0430\u0431\u044b, \u0441\u0430\u0439 \u043c\u0435\u0436\u0434\u0443 \u0421\u0430\u0444\u043e\u0439 \u0438 \u041c\u0430\u0440\u0432\u043e\u0439, \u0431\u0440\u0438\u0442\u044c\u0451 \u0438\u043b\u0438 \u0443\u043a\u043e\u0440\u0430\u0447\u0438\u0432\u0430\u043d\u0438\u0435 \u0432\u043e\u043b\u043e\u0441. \u0423 \u0445\u0430\u043d\u0430\u0444\u0438\u0442\u043e\u0432 \u0443\u043c\u0440\u0430 \u2014 \u0441\u0443\u043d\u043d\u0430 \u043c\u0443\u0430\u043a\u043a\u0430\u0434\u0430.")
B.aim=new A.q("\u0425\u0430\u0434\u0436","\u041a\u043e\u043c\u0443 \u0432\u0430\u0434\u0436\u0438\u0431 \u043a\u0443\u0440\u0431\u0430\u043d?","\u0421\u043e\u0432\u0435\u0440\u0448\u0435\u043d\u043d\u043e\u043b\u0435\u0442\u043d\u0435\u043c\u0443 \u043c\u0443\u0441\u0443\u043b\u044c\u043c\u0430\u043d\u0438\u043d\u0443, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u043d\u0435 \u0432 \u043f\u0443\u0442\u0438 \u0438 \u043e\u0431\u043b\u0430\u0434\u0430\u0435\u0442 \u043d\u0438\u0441\u0430\u0431\u043e\u043c \u0432 \u0434\u043d\u0438 \u041a\u0443\u0440\u0431\u0430\u043d-\u0430\u0439\u0442\u0430. \u0416\u0435\u0440\u0442\u0432\u0443 \u0440\u0435\u0436\u0443\u0442 \u0441 \u0443\u0442\u0440\u0430 \u043f\u0440\u0430\u0437\u0434\u043d\u0438\u043a\u0430, \u043f\u043e\u0441\u043b\u0435 \u043f\u0440\u0430\u0437\u0434\u043d\u0438\u0447\u043d\u043e\u0433\u043e \u043d\u0430\u043c\u0430\u0437\u0430, \u0434\u043e \u0437\u0430\u043a\u0430\u0442\u0430 \u0442\u0440\u0435\u0442\u044c\u0435\u0433\u043e \u0434\u043d\u044f.")
B.akC=new A.q("\u0425\u0430\u0434\u0436","\u041a\u0430\u043a\u043e\u0435 \u0436\u0438\u0432\u043e\u0442\u043d\u043e\u0435 \u043f\u043e\u0434\u0445\u043e\u0434\u0438\u0442 \u0434\u043b\u044f \u043a\u0443\u0440\u0431\u0430\u043d\u0430?","\u041e\u0432\u0446\u0430 \u0438\u043b\u0438 \u043a\u043e\u0437\u0430 \u043e\u0442 \u0433\u043e\u0434\u0430 (\u043a\u0440\u0443\u043f\u043d\u044b\u0439 \u044f\u0433\u043d\u0451\u043d\u043e\u043a \u2014 \u043e\u0442 \u043f\u043e\u043b\u0443\u0433\u043e\u0434\u0430), \u043a\u043e\u0440\u043e\u0432\u0430 \u043e\u0442 \u0434\u0432\u0443\u0445 \u043b\u0435\u0442, \u0432\u0435\u0440\u0431\u043b\u044e\u0434 \u043e\u0442 \u043f\u044f\u0442\u0438 \u043b\u0435\u0442. \u041a\u043e\u0440\u043e\u0432\u0443 \u0438\u043b\u0438 \u0432\u0435\u0440\u0431\u043b\u044e\u0434\u0430 \u043c\u043e\u0436\u043d\u043e \u0440\u0435\u0437\u0430\u0442\u044c \u0432\u0441\u043a\u043b\u0430\u0434\u0447\u0438\u043d\u0443 \u2014 \u0434\u043e \u0441\u0435\u043c\u0438 \u0447\u0435\u043b\u043e\u0432\u0435\u043a.")
B.alB=new A.q("\u0421\u0435\u043c\u044c\u044f","\u041a\u0430\u043a\u0438\u0435 \u0443\u0441\u043b\u043e\u0432\u0438\u044f \u0443 \u043d\u0438\u043a\u0430\u0445\u0430?","\u041f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u0438 \u0441\u043e\u0433\u043b\u0430\u0441\u0438\u0435 (\u0438\u0434\u0436\u0430\u0431 \u0438 \u043a\u0430\u0431\u0443\u043b\u044c) \u0432 \u043e\u0434\u043d\u043e\u043c \u0441\u043e\u0431\u0440\u0430\u043d\u0438\u0438 \u043f\u0440\u0438 \u0434\u0432\u0443\u0445 \u0441\u0432\u0438\u0434\u0435\u0442\u0435\u043b\u044f\u0445-\u043c\u0443\u0441\u0443\u043b\u044c\u043c\u0430\u043d\u0430\u0445 \u2014 \u0434\u0432\u0443\u0445 \u043c\u0443\u0436\u0447\u0438\u043d\u0430\u0445 \u0438\u043b\u0438 \u043c\u0443\u0436\u0447\u0438\u043d\u0435 \u0438 \u0434\u0432\u0443\u0445 \u0436\u0435\u043d\u0449\u0438\u043d\u0430\u0445. \u041e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u0435\u043d \u043c\u0430\u0445\u0440.")
B.aj1=new A.q("\u0421\u0435\u043c\u044c\u044f","\u0427\u0442\u043e \u0442\u0430\u043a\u043e\u0435 \u043c\u0430\u0445\u0440?","\u041e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u043f\u043e\u0434\u0430\u0440\u043e\u043a \u043c\u0443\u0436\u0430 \u0436\u0435\u043d\u0435 \u043f\u0440\u0438 \u043d\u0438\u043a\u0430\u0445\u0435 \u2014 \u0434\u0435\u043d\u044c\u0433\u0430\u043c\u0438 \u0438\u043b\u0438 \u0446\u0435\u043d\u043d\u043e\u0441\u0442\u044c\u044e. \u042d\u0442\u043e \u0435\u0451 \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0441\u0442\u044c, \u0438\u043c \u0440\u0430\u0441\u043f\u043e\u0440\u044f\u0436\u0430\u0435\u0442\u0441\u044f \u043e\u043d\u0430.")
B.al_=new A.q("\u0421\u0435\u043c\u044c\u044f","\u041a\u0442\u043e \u0442\u0430\u043a\u043e\u0439 \u043c\u0430\u0445\u0440\u0430\u043c?","\u0420\u043e\u0434\u0441\u0442\u0432\u0435\u043d\u043d\u0438\u043a, \u0431\u0440\u0430\u043a \u0441 \u043a\u043e\u0442\u043e\u0440\u044b\u043c \u0437\u0430\u043f\u0440\u0435\u0449\u0451\u043d \u043d\u0430\u0432\u0441\u0435\u0433\u0434\u0430: \u043e\u0442\u0435\u0446, \u0434\u0435\u0434, \u0441\u044b\u043d, \u0431\u0440\u0430\u0442, \u0434\u044f\u0434\u044f, \u043f\u043b\u0435\u043c\u044f\u043d\u043d\u0438\u043a, \u0430 \u0442\u0430\u043a\u0436\u0435 \u0442\u0435\u0441\u0442\u044c, \u0441\u0432\u0451\u043a\u043e\u0440 \u0438 \u043c\u043e\u043b\u043e\u0447\u043d\u044b\u0435 \u0440\u043e\u0434\u0441\u0442\u0432\u0435\u043d\u043d\u0438\u043a\u0438.")
B.alp=new A.q("\u0421\u0435\u043c\u044c\u044f","\u041f\u0440\u0430\u0432\u0430 \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439 \u0432 \u0438\u0441\u043b\u0430\u043c\u0435","\u041f\u043e\u0447\u0438\u0442\u0430\u0442\u044c \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439 \u2014 \u043e\u0434\u043d\u043e \u0438\u0437 \u043b\u0443\u0447\u0448\u0438\u0445 \u0434\u0435\u043b \u043f\u043e\u0441\u043b\u0435 \u0432\u0435\u0440\u044b: \u0441\u043b\u0443\u0448\u0430\u0442\u044c\u0441\u044f \u0438\u0445 \u0432 \u0434\u043e\u0437\u0432\u043e\u043b\u0435\u043d\u043d\u043e\u043c, \u0437\u0430\u0431\u043e\u0442\u0438\u0442\u044c\u0441\u044f \u0432 \u0441\u0442\u0430\u0440\u043e\u0441\u0442\u0438, \u043d\u0435 \u0433\u043e\u0432\u043e\u0440\u0438\u0442\u044c \u0438\u043c \u0434\u0430\u0436\u0435 \xab\u0443\u0444\xbb (\u041a\u043e\u0440\u0430\u043d, 17:23), \u0434\u0435\u043b\u0430\u0442\u044c \u0437\u0430 \u043d\u0438\u0445 \u0434\u0443\u0430 \u0438 \u043f\u043e\u0441\u043b\u0435 \u0438\u0445 \u0441\u043c\u0435\u0440\u0442\u0438.")
B.aif=new A.q("\u0425\u0430\u043b\u044f\u043b\u044c","\u041a\u0430\u043a\u043e\u0435 \u043c\u044f\u0441\u043e \u2014 \u0445\u0430\u043b\u044f\u043b\u044c?","\u041c\u044f\u0441\u043e \u0434\u043e\u0437\u0432\u043e\u043b\u0435\u043d\u043d\u043e\u0433\u043e \u0436\u0438\u0432\u043e\u0442\u043d\u043e\u0433\u043e, \u0437\u0430\u043a\u043e\u043b\u043e\u0442\u043e\u0433\u043e \u043c\u0443\u0441\u0443\u043b\u044c\u043c\u0430\u043d\u0438\u043d\u043e\u043c (\u0438\u043b\u0438 \u043b\u044e\u0434\u044c\u043c\u0438 \u041f\u0438\u0441\u0430\u043d\u0438\u044f) \u0441 \u043f\u0440\u043e\u0438\u0437\u043d\u0435\u0441\u0435\u043d\u0438\u0435\u043c \u0438\u043c\u0435\u043d\u0438 \u0410\u043b\u043b\u0430\u0445\u0430. \u041f\u043e \u0445\u0430\u043d\u0430\u0444\u0438\u0442\u0441\u043a\u043e\u043c\u0443 \u043c\u0430\u0437\u0445\u0430\u0431\u0443, \u0435\u0441\u043b\u0438 \xab\u0411\u0438\u0441\u043c\u0438\u043b\u043b\u044f\u0445\xbb \u043d\u0430\u043c\u0435\u0440\u0435\u043d\u043d\u043e \u043d\u0435 \u043f\u0440\u043e\u0438\u0437\u043d\u0435\u0441\u043b\u0438, \u043c\u044f\u0441\u043e \u0445\u0430\u0440\u0430\u043c.")
